export const PERMISSIONS = {
    VIEW_DASHBOARD: 'VIEW_DASHBOARD',
    MANAGE_SYSTEM_CONFIG: 'MANAGE_SYSTEM_CONFIG',
    MANAGE_USERS: 'MANAGE_USERS',
    VIEW_VENDORS: 'VIEW_VENDORS',
    MANAGE_VENDORS: 'MANAGE_VENDORS',
    VIEW_ORDERS: 'VIEW_ORDERS',
    MANAGE_ORDERS: 'MANAGE_ORDERS',
    VIEW_PAYMENTS: 'VIEW_PAYMENTS',
    APPROVE_REFUNDS: 'APPROVE_REFUNDS',
    VIEW_SETTLEMENTS: 'VIEW_SETTLEMENTS',
    MANAGE_SETTLEMENTS: 'MANAGE_SETTLEMENTS',
    MANAGE_DELIVERY: 'MANAGE_DELIVERY',
    VIEW_SUPPORT: 'VIEW_SUPPORT',
    VIEW_CUSTOMER_PROFILE: 'VIEW_CUSTOMER_PROFILE',
    MANAGE_SUPPORT: 'MANAGE_SUPPORT',
    MANAGE_OWN_ORDERS: 'MANAGE_OWN_ORDERS',
    VIEW_OWN_SCOPE: 'VIEW_OWN_SCOPE',
    MANAGE_GIFT_CARDS: 'MANAGE_GIFT_CARDS'
};
const all = Object.values(PERMISSIONS);
export const ROLE_PERMISSIONS = {
    SUPER_ADMIN: all,
    ADMIN: all,
    OPERATIONS_ADMIN: [PERMISSIONS.VIEW_DASHBOARD, PERMISSIONS.VIEW_VENDORS, PERMISSIONS.MANAGE_VENDORS, PERMISSIONS.VIEW_ORDERS, PERMISSIONS.MANAGE_ORDERS, PERMISSIONS.MANAGE_DELIVERY, PERMISSIONS.VIEW_SUPPORT],
    FINANCE_ADMIN: [PERMISSIONS.VIEW_DASHBOARD, PERMISSIONS.MANAGE_GIFT_CARDS, PERMISSIONS.VIEW_ORDERS, PERMISSIONS.VIEW_PAYMENTS, PERMISSIONS.APPROVE_REFUNDS, PERMISSIONS.VIEW_SETTLEMENTS, PERMISSIONS.MANAGE_SETTLEMENTS, PERMISSIONS.VIEW_VENDORS],
    VENDOR_MANAGER: [PERMISSIONS.VIEW_DASHBOARD, PERMISSIONS.VIEW_VENDORS, PERMISSIONS.MANAGE_VENDORS, PERMISSIONS.VIEW_ORDERS],
    DELIVERY_MANAGER: [PERMISSIONS.VIEW_DASHBOARD, PERMISSIONS.VIEW_ORDERS, PERMISSIONS.MANAGE_DELIVERY, PERMISSIONS.VIEW_SETTLEMENTS],
    SUPPORT_LEAD: [PERMISSIONS.VIEW_DASHBOARD, PERMISSIONS.VIEW_ORDERS, PERMISSIONS.VIEW_SUPPORT, PERMISSIONS.MANAGE_SUPPORT, PERMISSIONS.VIEW_VENDORS, PERMISSIONS.VIEW_CUSTOMER_PROFILE],
    SUPPORT_AGENT: [PERMISSIONS.VIEW_ORDERS, PERMISSIONS.VIEW_SUPPORT, PERMISSIONS.MANAGE_SUPPORT, PERMISSIONS.VIEW_OWN_SCOPE, PERMISSIONS.VIEW_CUSTOMER_PROFILE],
    VENDOR_OWNER: [PERMISSIONS.VIEW_ORDERS, PERMISSIONS.VIEW_OWN_SCOPE, PERMISSIONS.MANAGE_OWN_ORDERS, PERMISSIONS.VIEW_SETTLEMENTS, PERMISSIONS.VIEW_SUPPORT],
    VENDOR_STAFF: [PERMISSIONS.VIEW_ORDERS, PERMISSIONS.VIEW_OWN_SCOPE, PERMISSIONS.MANAGE_OWN_ORDERS, PERMISSIONS.VIEW_SUPPORT],
    DELIVERY_PARTNER: [PERMISSIONS.VIEW_ORDERS, PERMISSIONS.VIEW_OWN_SCOPE, PERMISSIONS.VIEW_SUPPORT],
    CUSTOMER: [PERMISSIONS.VIEW_OWN_SCOPE, PERMISSIONS.VIEW_SUPPORT]
};
export function hasPermission(role, permission) {
    return ROLE_PERMISSIONS[role]?.includes(permission) ?? false;
}
